const slots = $slots;
const minutesOf = (hour) => hour * 60;
const lastTicket = minutesOf(slots.openUntil) - 30;
const ticketOk = (minutes) => minutes <= lastTicket;
const from = minutesOf(slots.breakFrom);
const until = minutesOf(slots.breakUntil);
const firstOk = ticketOk(slots.first.hour);
const secondOk = ticketOk(slots.second.hour);
if (firstOk && secondOk) { throw new Error("both attempts get a ticket"); }
if (firstOk) { throw new Error("the first attempt gets a ticket"); }
if (secondOk) { throw new Error("the second attempt gets a ticket"); }
const suffix = firstOk ? "First" : "Second";
return "Only " + suffix + " attempt: " + slots.first.day + " " + slots.first.hour + ": " + (firstOk ? "yes" : "no") + "; " + slots.second.day + " " + slots.second.hour + ": " + (secondOk ? "yes" : "no") + ".";

