const slots = $slots;
const applies = (subject, verb, object) => object.match(new RegExp(verb + " " + object));
const shieldClause = applies(slots.apprentice, slots.ruleOneVerb, slots.ruleOneObject) ? "Yes." : "No.";
const storeClause = !slots.lampOn ? "The store is dark." : "The store is not dark.";
const skipClause = slots.skipVerb === "may" ? "May not skip." : "May skip.";
return shieldClause + " " + storeClause + " " + skipClause;

